@@ -0,0 +1,38 @@
+opam-version: "2.0"
+maintainer: "Alan Hu <ahulambda@gmail.com>"
+authors: "The LLVM team"
+homepage: "http://llvm.org"
+bug-reports: "https://llvm.org/bugs/"
+license: "MIT"
+build: [
+  ["bash" "configure.sh" version "shared"]
+]
+depends: [
+  "conf-bash" {build}
+]
+depexts: [
+  ["llvm@20" "zstd"] {os-distribution = "homebrew" & os = "macos"}
+  ["llvm-20"] {os-distribution = "macports" & os = "macos"}
+  ["llvm-20-dev" "zlib1g-dev" "libzstd-dev"] {os-family = "debian"}
+  ["llvm20-dev"] {os-distribution = "alpine"}
+  ["llvm20"] {os-family = "arch"}
+  ["llvm20-devel"] {os-family = "suse" | os-family = "opensuse"}
+  ["llvm20-devel"] {os-distribution = "fedora" & os-version >= "43"}
+  ["llvm-devel"] {os-distribution = "fedora" & os-version = "42"}
+  ["llvm20-devel" "epel-release"] {os-distribution = "centos"}
+  ["devel/llvm20"] {os = "freebsd"}
+]
+synopsis: "Virtual package relying on llvm shared library installation"
+flags: conf
+extra-source "configure.sh" {
+  src:
+    "https://raw.githubusercontent.com/ocaml/opam-source-archives/refs/heads/main/patches/conf-llvm/configure.sh.18"
+  checksum: [
+    "sha256=3675ad30b93aab67f1d57aa7c700800a3b5954768610ef9ef29bba7483f16936"
+    "md5=409c0a03dcea76a45719b80a06e2bd71"
+  ]
+}
+x-ci-accept-failures: [
+  "centos-9"
+  "centos-10"
+]

